<template>
    <div class="mi-page"><div class="content-header"><div class="container-fluid"><h5 class="m-0">{{ title }}</h5></div></div>
    <div class="content"><div class="container-fluid"><div class="card card-primary"><form @submit.prevent="submit"><div class="card-body"><div class="mx-auto col-md-6"><div class="form-group"><label>Материал</label><select v-model.number="form.nomenclature_id" class="form-control" :class="{'is-invalid': errors.nomenclature_id}"><option :value="null">Выберите материал</option><option v-for="item in materials" :value="item.id">{{ item.name }} ({{ item.unit }})</option></select><div class="invalid-feedback">{{ errors.nomenclature_id }}</div></div><div class="form-group"><label>Количество</label><input v-model="form.quantity" type="number" step="0.000001" min="0" class="form-control" :class="{'is-invalid': errors.quantity}"><div class="invalid-feedback">{{ errors.quantity }}</div></div><div v-if="operation === 'return_in'" class="form-group"><label>Выпуск производства (необязательно)</label><select v-model="form.production_run_id" class="form-control"><option value="">Без связи с выпуском</option><option v-for="run in runs" :value="run.id">{{ run.name }}</option></select></div><div class="form-group"><label>Дата и время</label><input v-model="form.occurred_at" type="datetime-local" class="form-control" :class="{'is-invalid': errors.occurred_at}"><div class="invalid-feedback">{{ errors.occurred_at }}</div></div><div class="form-group"><label>Комментарий</label><textarea v-model="form.comment" class="form-control"></textarea></div></div></div><div class="card-footer mi-actions"><button class="btn btn-primary" :disabled="form.processing">{{ form.processing ? 'Сохранение...' : 'Сохранить' }}</button><Link :href="route('material-inventory.balances')" class="btn btn-default">Отмена</Link></div></form></div></div></div></div>
</template>
<script>
import {Head, Link, useForm} from '@inertiajs/inertia-vue3';
export default {components: {Head, Link}, props: ['operation', 'materials', 'runs', 'errors'], data() { return {form: useForm({nomenclature_id: null, quantity: null, occurred_at: new Date().toISOString().slice(0, 16), comment: '', production_run_id: ''})} }, computed: {title() { return {receipt: 'Поступление материала', write_off: 'Списание материала', return_in: 'Возврат материала на склад', adjustment_in: 'Корректировка остатка: увеличение', adjustment_out: 'Корректировка остатка: уменьшение'}[this.operation]}}, methods: {submit() { const name = {receipt: 'receipt.store', write_off: 'write-off.store', return_in: 'return.store', adjustment_in: 'adjustment-in.store', adjustment_out: 'adjustment-out.store'}[this.operation]; this.form.post(route('material-inventory.' + name)) }}};
</script>
